/// Range of `addr` for family `fam`; nullptr when the register has no generated range.
inline const InstallerRange *installer_range(sungrow_modbus::XmlFamily fam, uint16_t addr) {
  const InstallerRange *a = nullptr;
  size_t n = 0;
  switch (fam) {
    case sungrow_modbus::XmlFamily::STR_PV:
      a = INSTALLER_RANGES_STR_PV;
      n = sizeof(INSTALLER_RANGES_STR_PV) / sizeof(InstallerRange);
      break;
    case sungrow_modbus::XmlFamily::RES_ES:
      a = INSTALLER_RANGES_RES_ES;
      n = sizeof(INSTALLER_RANGES_RES_ES) / sizeof(InstallerRange);
      break;
    case sungrow_modbus::XmlFamily::RES_NEW_PV:
      a = INSTALLER_RANGES_RES_NEW_PV;
      n = sizeof(INSTALLER_RANGES_RES_NEW_PV) / sizeof(InstallerRange);
      break;
    case sungrow_modbus::XmlFamily::UNIT:
      a = INSTALLER_RANGES_UNIT;
      n = sizeof(INSTALLER_RANGES_UNIT) / sizeof(InstallerRange);
      break;
    default:
      return nullptr;
  }
  size_t lo = 0, hi = n;
  while (lo < hi) {
    size_t mid = (lo + hi) / 2;
    if (a[mid].addr < addr)
      lo = mid + 1;
    else
      hi = mid;
  }
  return lo < n && a[lo].addr == addr ? &a[lo] : nullptr;
}

/// Relations of `addr` (lhs == addr) for family `fam`: *out / *n, false when there are none.
inline bool installer_rels(sungrow_modbus::XmlFamily fam, uint16_t addr, const InstallerRel **out,
                           size_t *n) {
  const InstallerRel *a = nullptr;
  size_t cnt = 0;
  switch (fam) {
    case sungrow_modbus::XmlFamily::STR_PV:
      a = INSTALLER_RELS_STR_PV;
      cnt = sizeof(INSTALLER_RELS_STR_PV) / sizeof(InstallerRel);
      break;
    case sungrow_modbus::XmlFamily::RES_ES:
      a = INSTALLER_RELS_RES_ES;
      cnt = sizeof(INSTALLER_RELS_RES_ES) / sizeof(InstallerRel);
      break;
    case sungrow_modbus::XmlFamily::RES_NEW_PV:
      a = INSTALLER_RELS_RES_NEW_PV;
      cnt = sizeof(INSTALLER_RELS_RES_NEW_PV) / sizeof(InstallerRel);
      break;
    case sungrow_modbus::XmlFamily::UNIT:
      a = INSTALLER_RELS_UNIT;
      cnt = sizeof(INSTALLER_RELS_UNIT) / sizeof(InstallerRel);
      break;
    default:
      break;
  }
  size_t lo = 0, hi = cnt;
  while (lo < hi) {
    size_t mid = (lo + hi) / 2;
    if (a[mid].lhs < addr)
      lo = mid + 1;
    else
      hi = mid;
  }
  size_t end = lo;
  while (end < cnt && a[end].lhs == addr)
    end++;
  *out = end > lo ? &a[lo] : nullptr;
  *n = end - lo;
  return end > lo;
}

